<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;

final class ClientIdentityTrustedClientVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TrustedClientRef('one');
        $ref = ClientIdentityTrustedClientVO::from($value);
        $this->assertEquals(new TrustedClientRef('one'), $ref->value());
        $other = ClientIdentityTrustedClientVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = ClientIdentityTrustedClientVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = ClientIdentityTrustedClientVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_empty(): void
    {
        $ref = ClientIdentityTrustedClientVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = ClientIdentityTrustedClientVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
